const { URL } = require('url');
const r = $json;
let placeId = null;
if (r.google_maps_url) {
  let url;
  try { url = new URL(r.google_maps_url); } catch { throw new Error('P02:INVALID_PLACE_ID'); }
  placeId = url.searchParams.get('query_place_id') || url.searchParams.get('place_id');
  if (!placeId) {
    const match = r.google_maps_url.match(/!1s(ChIJ[A-Za-z0-9_-]+)/);
    if (match) placeId = match[1];
  }
}
return { json: { ...r, place_id: placeId || null } };

const original = $('Atomically Claim One Request').item.json;
const origin = $prevNode.name;
const err = $json.error ?? $json;
const message = [typeof err === 'string' ? err : null, err?.message, err?.description, err?.code, err?.cause?.message, $json.message].filter(x => typeof x === 'string').join(' ');
const marker = ['Validate Resolved Business', 'Extract Exact Google Place ID'].includes(origin) ? message.match(/P02:(BUSINESS_NOT_FOUND|BUSINESS_AMBIGUOUS|INVALID_PLACE_ID|BUSINESS_IDENTITY_MISMATCH|BUSINESS_LOCATION_MISMATCH|CONNECTION_ERROR|TIMEOUT|RATE_LIMIT|AUTHENTICATION_ERROR|API_CONTRACT_ERROR|PERSISTENCE_ERROR|BUDGET_LIMIT|SUBMISSION_UNCERTAIN|PERMANENT_ERROR)(?::([0-9]{3,5}))?/) : null;
const rawCode = String(err?.httpCode ?? err?.statusCode ?? err?.code ?? '');
const knownCodes = new Set(['ETIMEDOUT', 'ESOCKETTIMEDOUT', 'ECONNRESET', 'ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN', 'EHOSTUNREACH', 'ENETUNREACH']);
const code = marker?.[2] ?? (/^[0-9]{3,5}$/.test(rawCode) || knownCodes.has(rawCode) ? rawCode : null);
let category;
if (marker) category = marker[1];
else if (origin === 'Has Verifiable Place ID') category = 'BUSINESS_AMBIGUOUS';
else if (origin === 'Extract Exact Google Place ID') category = 'INVALID_PLACE_ID';
else if (code === '401' || code === '403') category = 'AUTHENTICATION_ERROR';
else if (code === '429') category = 'RATE_LIMIT';
else if (/ETIMEDOUT|ESOCKETTIMEDOUT|timeout|timed out/i.test(message)) category = 'TIMEOUT';
else if (/ECONN|ENOTFOUND|EAI_AGAIN|socket hang up|network/i.test(message)) category = 'CONNECTION_ERROR';
else if (origin === 'Validate Resolved Business' || origin === 'Build Nine Standard Tasks' || origin === 'Associate and Classify task_post Response') category = 'API_CONTRACT_ERROR';
else if (origin.includes('Persist') || origin.includes('Record Failed') || origin.includes('Authorize') || origin === 'Log Persisted Submission Outcomes') category = 'PERSISTENCE_ERROR';
else if (code && Number(code) >= 500) category = 'CONNECTION_ERROR';
else category = 'PERMANENT_ERROR';
const node = marker && origin === 'Validate Resolved Business' && ['BUSINESS_NOT_FOUND', 'INVALID_PLACE_ID', 'AUTHENTICATION_ERROR', 'RATE_LIMIT', 'CONNECTION_ERROR'].includes(category) ? 'Resolve Exact Place Details' : origin;
return { json: { request_id: original.request_id, claim_token: original.claim_token, node, category, code, execution_id: String($execution.id) } };

const r = $('Extract Exact Google Place ID').item.json;
const p = $json.body ?? $json;
const providerCode = Number(p?.error?.code);
if (Number.isInteger(providerCode)) {
  const category = providerCode === 404 ? 'BUSINESS_NOT_FOUND' : [401, 403].includes(providerCode) ? 'AUTHENTICATION_ERROR' : providerCode === 429 ? 'RATE_LIMIT' : providerCode >= 500 ? 'CONNECTION_ERROR' : providerCode === 400 ? 'INVALID_PLACE_ID' : 'PERMANENT_ERROR';
  throw new Error(`P02:${category}:${providerCode}`);
}
if (!p || !p.id || !p.location || !Number.isFinite(p.location.latitude) || !Number.isFinite(p.location.longitude)) throw new Error('P02:API_CONTRACT_ERROR');
const name = p.displayName?.text || '';
const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const requestedName = normalize(r.company_name);
const resolvedName = normalize(name);
if (!requestedName || !resolvedName || !(resolvedName.includes(requestedName) || requestedName.includes(resolvedName))) throw new Error('P02:BUSINESS_IDENTITY_MISMATCH');
const crypto = require('crypto');
const businessId = 'gplaces-' + crypto.createHash('sha256').update(p.id).digest('hex').slice(0, 40);
return { json: { ...r, business_id: businessId, resolved_place_id: p.id, resolved_name: name, center_lat: p.location.latitude, center_lng: p.location.longitude, address: p.formattedAddress || `${r.city}, ${r.state}`, category: p.primaryTypeDisplayName?.text || null } };

const scan = $json;
const request = $('Extract Exact Google Place ID').item.json;
if (!scan.scan_id || scan.grid_size !== 3 || scan.spacing_km !== 1 || scan.total !== 9 || scan.points?.length !== 9 || scan.language_code !== 'pt') throw new Error('Smart Grid returned an unexpected external scan contract');
const tasks = scan.points.map(p => ({ keyword: scan.keyword, location_coordinate: `${p.lat},${p.lng},14z`, language_code: 'pt', priority: 1, depth: 20, tag: `${request.request_id}:${p.row}:${p.col}` }));
return { json: { request_id: request.request_id, claim_token: request.claim_token, scan_id: scan.scan_id, business_id: scan.business_id, center: scan.center, points: scan.points.map(p => ({ row: p.row, col: p.col, lat: p.lat, lng: p.lng })), tasks } };

const response = $json.body ?? $json;
const build = $('Build Nine Standard Tasks').item.json;
const expected = build.tasks;
const code = Number(response.status_code);
const message = typeof response.status_message === 'string' ? response.status_message : null;
const categories = { 401: 'authentication_error', 40100: 'authentication_error', 40104: 'authentication_error', 402: 'insufficient_balance', 40200: 'insufficient_balance', 40201: 'access_denied', 40202: 'rate_limit', 40203: 'budget_limit', 40205: 'duplicate_task_limit', 40206: 'duplicate_task_limit', 40209: 'rate_limit', 40210: 'insufficient_balance', 40000: 'request_error', 40001: 'request_error', 40006: 'request_error', 50000: 'technical_error', 50301: 'technical_error', 50401: 'technical_error', 50402: 'technical_error' };
let mapped;
if (code !== 20000 && (!Array.isArray(response.tasks) || response.tasks.length === 0)) {
  mapped = expected.map((t, i) => ({ row: build.points[i].row, col: build.points[i].col, task_id: null, status_code: code || null, status_message: message, cost: null, error_category: categories[code] || 'technical_error', error_message: message || 'DataForSEO rejected task_post' }));
} else {
  const tasks = Array.isArray(response.tasks) ? response.tasks : [];
  const byTag = new Map(tasks.map(t => [t.data?.tag || t.tag, t]).filter(([tag]) => tag));
  mapped = expected.map((input, i) => {
    let t = byTag.get(input.tag);
    if (!t && tasks.length === expected.length) {
      t = tasks.find(candidate => candidate.data?.location_coordinate === input.location_coordinate);
    }
    if (!t) return { row: build.points[i].row, col: build.points[i].col, task_id: null, status_code: null, status_message: 'Response could not be reliably associated with a grid point', cost: null, error_category: 'technical_error', error_message: 'Missing task tag/coordinate; manual reconciliation required' };
    const taskCode = Number(t.status_code);
    return { row: build.points[i].row, col: build.points[i].col, task_id: t.id || null, status_code: Number.isFinite(taskCode) ? taskCode : null, status_message: t.status_message || message, cost: t.cost == null ? null : Number(t.cost), error_category: categories[taskCode] || (t.id ? null : 'technical_error'), error_message: t.id ? null : (t.status_message || message || 'No DataForSEO task ID returned') };
  });
}
const taskCostsKnown = mapped.every(t => Number.isFinite(t.cost) && t.cost >= 0);
const totalCostKnown = response.cost != null && Number.isFinite(Number(response.cost)) && Number(response.cost) >= 0;
const totalCost = totalCostKnown ? Number(response.cost) : (taskCostsKnown ? mapped.reduce((sum, t) => sum + t.cost, 0) : null);
return { json: { request_id: build.request_id, claim_token: build.claim_token, task_results: mapped, total_cost_usd: totalCost } };

const outcome = $('Associate and Classify task_post Response').item.json;
const build = $('Build Nine Standard Tasks').item.json;
const coords = new Map(build.points.map(p => [`${p.row}:${p.col}`, p]));
const points = outcome.task_results.filter(t => !t.task_id && Number.isInteger(t.status_code) && ((t.status_code >= 40000 && t.status_code < 50000) || [401, 402].includes(t.status_code))).map(t => { const p = coords.get(`${t.row}:${t.col}`); return { row: t.row, col: t.col, lat: p.lat, lng: p.lng, status: 'error', results: [], error: t.error_message || t.status_message || 'DataForSEO rejected the task', error_category: t.error_category || 'technical_error', api_status_code: t.status_code, api_status_message: t.status_message }; });
return { json: { request_id: outcome.request_id, scan_id: build.scan_id, points, point_cells: points.map(p => ({ row_index: p.row, col_index: p.col })) } };
